def transform(grid):
    out = [row[:] for row in grid]
    pts = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == 5]
    r0, r1 = min(r for r, c in pts), max(r for r, c in pts)
    c0, c1 = min(c for r, c in pts), max(c for r, c in pts)

    # The frame is reproduced as successively smaller rectangular outlines:
    # blue (2) outlines are separated by one-cell 5 outlines.
    for r in range(r0 + 1, r1):
        for c in range(c0 + 1, c1):
            d = min(r-r0, r1-r, c-c0, c1-c)
            if d == 1:
                color = 2
            elif d % 2 == 0:
                color = 5
            else:
                color = 0
            out[r][c] = color
    return out
